package com.interview.fraud.platform;
import java.time.Instant; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component;
@Component public class OutboxPublisher {private final JdbcTemplate jdbc;private final KafkaTemplate<String,String> kafka;private final boolean enabled;public OutboxPublisher(JdbcTemplate j,KafkaTemplate<String,String> k,@Value("${app.kafka-enabled:false}")boolean e){jdbc=j;kafka=k;enabled=e;}@Scheduled(fixedDelayString="${app.outbox-delay-ms:1000}")public void publish(){if(!enabled)return;for(var row:jdbc.queryForList("SELECT id,aggregate_id,event_type,payload FROM outbox_events WHERE status='PENDING' AND attempts<5 ORDER BY created_at LIMIT 50")){UUID id=(UUID)row.get("id");try{kafka.send("fraud-domain-events",String.valueOf(row.get("aggregate_id")),String.valueOf(row.get("payload"))).get();jdbc.update("UPDATE outbox_events SET status='PUBLISHED',published_at=? WHERE id=?",Instant.now(),id);}catch(Exception e){jdbc.update("UPDATE outbox_events SET attempts=attempts+1 WHERE id=?",id);}}}}
